settings.custom_css:
.main-wrap {
    display: flex;
    flex-wrap: wrap;
    max-width: 600px;
    margin-top: 15px;
    margin-left: auto;
    margin-right: auto;
}
.main-wrap p{
    margin: 0;
    text-align: left;
}
div.wrap {
    display: flex;
    align-items: start;
    margin: 5px;
    justify-content: center;
}
.twocol {
    flex-basis: calc(50% - 20px);
}
div.wrap img {
    margin-right: 10px;
    margin-top: 3px;
}
#hp-sld .swiper-slide-bg{
 background-position: 93% 50%;
 background-size: 550px;
}
.swiper-slide-inner {
    max-width: 1260px;
}
div.sec{
    font-size: 40px;
    margin-top: 5px;
}
#hp-sld .elementor-swiper-button{
    border-radius: 50px;
    border: 2px solid #d7b754;
    padding: 8px;
}
#hp-sld .elementor-button.elementor-slide-button:hover{
    transform: scale(0.92);
}
#hp-sld .elementor-swiper-button.elementor-swiper-button-prev{
    background:#0c4f4e url(/wp-content/uploads/2024/04/lft-arw.webp) no-repeat center;

}
#hp-sld .elementor-swiper-button.elementor-swiper-button-prev:hover{
    background:#d7b754 url(/wp-content/uploads/2024/04/lft-arw.webp) no-repeat center;
}
#hp-sld .elementor-swiper-button.elementor-swiper-button-next{
    background:#0c4f4e url(/wp-content/uploads/2024/04/arw-right.webp) no-repeat center;
}
#hp-sld .elementor-swiper-button.elementor-swiper-button-next:hover{
    background:#d7b754 url(/wp-content/uploads/2024/04/arw-right.webp) no-repeat center;
}
@media (min-width: 1600px){
    #hp-sld .swiper-slide-bg{
 background-position: 80% 50%;
}
}
@media (min-width: 1920px){
    #hp-sld .swiper-slide-bg{
 background-position: 75% 50%;
}
}
@media (max-width: 1024px){
div.sec{
    font-size: 28px;
} 
#hp-sld .swiper-slide-bg{
 background-size: 280px;
}
}
@media (max-width: 767px){
div.sec{
    font-size: 20px;

} 
#hp-sld .swiper-slide-bg{
 background-position: 50% 1%;
 background-size: 250px;
}
#hp-sld .elementor-swiper-button   {
     transform: scale(0.8);
 }
 .main-wrap{
   display: block;
   flex-wrap: nowrap;
 }
 div.wrap {
    justify-content: start;
}
.twocol {
    flex-basis: 100%;
}
}

